<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio OS V15.4 — Strategic Execution Control */
function tuff_beatz_v154_key($i){return substr(hash('sha256',($i['type']??'').'|'.($i['objective']??'').'|'.($i['metric']??'')),0,20);}
function tuff_beatz_v154_state(){ $v=get_option('_tb_v154_execution_state',array());return is_array($v)?$v:array(); }
function tuff_beatz_v154_actions(){if(!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())return;$a=sanitize_key($_POST['tb_v154_action']??'');if(!$a)return;check_admin_referer('tb_v154_execution','tb_v154_nonce');$key=sanitize_text_field($_POST['objective_key']??'');if(!$key)wp_safe_redirect(home_url('/business-command/'));$state=tuff_beatz_v154_state();$row=$state[$key]??array('status'=>'proposed','owner'=>get_current_user_id(),'progress'=>0,'updated_at'=>'');if($a==='approve')$row['status']='approved';elseif($a==='start'&&in_array($row['status'],array('approved','paused'),true))$row['status']='active';elseif($a==='pause'&&$row['status']==='active')$row['status']='paused';elseif($a==='complete'&&in_array($row['status'],array('approved','active','paused'),true)){$row['status']='completed';$row['progress']=100;}elseif($a==='progress'&&in_array($row['status'],array('approved','active','paused'),true))$row['progress']=max(0,min(100,(int)($_POST['progress']??0)));$row['owner']=get_current_user_id();$row['updated_at']=current_time('mysql');$state[$key]=$row;update_option('_tb_v154_execution_state',$state,false);wp_safe_redirect(home_url('/business-command/#strategic-execution'));exit;}
add_action('admin_post_tb_v154_execution','tuff_beatz_v154_actions');
function tuff_beatz_v154_panel(){if(!is_page('business-command')||!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())return;$items=function_exists('tuff_beatz_v153_objectives')?tuff_beatz_v153_objectives():array();$state=tuff_beatz_v154_state();ob_start();?><section class="tb-v154-exec" id="strategic-execution"><div class="tb-v154-head"><div><small>STRATEGIC EXECUTION CONTROL • V15.4</small><h3>Human-Controlled Initiative Board</h3><p>Strategic objectives remain proposals until explicitly approved. Progress and execution state require producer action.</p></div></div><div class="tb-v154-list"><?php foreach($items as $i):$k=tuff_beatz_v154_key($i);$r=$state[$k]??array('status'=>'proposed','progress'=>0);?><article><div><small><?php echo esc_html($i['priority'].' • '.$i['type']);?></small><h4><?php echo esc_html($i['objective']);?></h4><p><?php echo esc_html($i['metric']);?><?php echo $i['target']!==null?' • Target '.esc_html(number_format((float)$i['target'],1)).'%':'';?></p></div><div class="tb-v154-state"><b><?php echo esc_html(strtoupper($r['status']));?></b><span><?php echo esc_html((int)$r['progress']);?>% PROGRESS</span></div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="tb_v154_execution"><input type="hidden" name="objective_key" value="<?php echo esc_attr($k);?>"><?php wp_nonce_field('tb_v154_execution','tb_v154_nonce');?><?php if($r['status']==='proposed'):?><button name="tb_v154_action" value="approve">APPROVE</button><?php elseif($r['status']==='approved'):?><button name="tb_v154_action" value="start">START</button><?php elseif($r['status']==='active'):?><button name="tb_v154_action" value="pause">PAUSE</button><?php elseif($r['status']==='paused'):?><button name="tb_v154_action" value="start">RESUME</button><?php endif;?><?php if($r['status']!=='proposed'&&$r['status']!=='completed'):?><label><input type="number" name="progress" min="0" max="100" value="<?php echo esc_attr((int)$r['progress']);?>"><button name="tb_v154_action" value="progress">UPDATE</button></label><button name="tb_v154_action" value="complete">COMPLETE</button><?php endif;?></form></article><?php endforeach;?></div><p class="tb-v154-foot">V15.4 records approval, status and progress only. It does not automatically alter opportunities, pricing, contracts, payments, client records, project status or financial data.</p></section><?php $html=ob_get_clean();?><script>document.addEventListener('DOMContentLoaded',function(){var a=document.querySelector('.tb-v153-plan');if(!a||document.querySelector('.tb-v154-exec'))return;var b=document.createElement('div');b.innerHTML=<?php echo wp_json_encode($html);?>;a.insertAdjacentElement('afterend',b.firstElementChild);var e=document.querySelector('.tb-biz-hero .eyebrow');if(e)e.textContent='TUFF BEATZ • EXECUTION CONTROL V15.4';});</script><?php }
add_action('wp_footer','tuff_beatz_v154_panel',20);
function tuff_beatz_v154_css(){if(!is_page('business-command'))return;wp_add_inline_style('tuff-beatz-business-command','.tb-v154-exec{margin-top:18px;padding:22px;border:1px solid rgba(216,180,90,.18);border-radius:18px;background:#090909}.tb-v154-head small{color:#a48748;font-size:.52rem;letter-spacing:.14em}.tb-v154-head h3{margin:4px 0;color:#e1d6c2;font-family:Cinzel,serif}.tb-v154-head p,.tb-v154-foot{color:#756d61;font-size:.55rem;line-height:1.5}.tb-v154-list{display:grid;gap:8px;margin-top:14px}.tb-v154-list article{display:grid;grid-template-columns:1fr 120px 270px;gap:14px;align-items:center;padding:13px;border:1px solid rgba(255,255,255,.05);border-radius:11px}.tb-v154-list small{color:#8f7747;font-size:.45rem}.tb-v154-list h4{margin:4px 0;color:#d9cfbd;font-size:.68rem}.tb-v154-list p,.tb-v154-state span{margin:0;color:#776f64;font-size:.5rem}.tb-v154-state b{display:block;color:#c8ab5d;font-size:.55rem}.tb-v154-state span{display:block;margin-top:3px}.tb-v154-list form{display:flex;gap:5px;flex-wrap:wrap;justify-content:flex-end}.tb-v154-list button{border:1px solid rgba(205,171,84,.3);background:#111;color:#c8aa5a;border-radius:7px;padding:6px 8px;font-size:.44rem;cursor:pointer}.tb-v154-list label{display:flex;gap:4px}.tb-v154-list input[type=number]{width:55px;background:#0b0b0b;color:#cfc5b2;border:1px solid rgba(255,255,255,.09);border-radius:6px;padding:5px}.tb-v154-foot{margin:10px 0 0}@media(max-width:850px){.tb-v154-list article{grid-template-columns:1fr}.tb-v154-list form{justify-content:flex-start}}');}
add_action('wp_enqueue_scripts','tuff_beatz_v154_css',116);
